1	package app
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"regexp"
8		"strings"
9		"sync"
10		"testing"
11		"time"
12	
13		tea "charm.land/bubbletea/v2"
14		"github.com/charmbracelet/colorprofile"
15	
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17		"github.com/anthnel/devdesk/internal/ui/theme"
18	)
19	
20	// DEVDESK-209 step 4: the terminal background is set and restored by Bubble
21	// Tea, proven on the bytes a real tea.Program writes (no TTY). These pin the
22	// framework's contract: a version bump that breaks it fails here.
23	//
24	// A panic test makes Bubble Tea print the stack trace to stderr; that is
25	// accepted noise.
26	
27	const (
28		bgReset = "\x1b]111\x07"
29		bgSet   = "\x1b]11;"
30	)
31	
32	var bgSeqRe = regexp.MustCompile("\x1b\\](111|11;[^\x07\x1b]*)(\x07|\x1b\\\\)")
33	
34	// bgSequences returns the ordered "set background" (OSC 11) and "reset
35	// background" (OSC 111) sequences found in out. Both are searched as whole
36	// sequences because they share the ESC ] 11 prefix.
37	func bgSequences(out string) []string {
38		var seqs []string
39		for _, m := range bgSeqRe.FindAllStringSubmatch(out, -1) {
40			if m[1] == "111" {
41				seqs = append(seqs, bgReset)
42			} else {
43				seqs = append(seqs, "\x1b]"+m[1]+"\x07")
44			}
45		}
46		return seqs
47	}
48	
49	func setOf(hex string) string { return bgSet + hex + "\x07" }
50	
51	// waitOut polls until cond(out) holds. It returns an error after a guard
52	// timeout; it never touches a *testing.T, so it is safe from the script
53	// goroutine.
54	func waitOut(out *lockedBuffer, what string, cond func(string) bool) error {
55		deadline := time.Now().Add(5 * time.Second)
56		for !cond(out.String()) {
57			if time.Now().After(deadline) {
58				return fmt.Errorf("timed out waiting for %s; output so far: %q", what, out.String())
59			}
60			time.Sleep(5 * time.Millisecond)
61		}
62		return nil
63	}
64	
65	// routerScript drives the program once the first frame is out. It returns an
66	// error instead of failing the test: it runs on its own goroutine.
67	type routerScript func(p *tea.Program, out *lockedBuffer) error
68	
69	// runRouter runs a around a real program writing to a buffer, after the first
70	// frame ("hello") script runs; the program is given profile. It always waits
71	// for the script goroutine before returning, so the script never outlives the
72	// test. A script error fails the test and kills the program; the program
73	// outliving a guard timeout fails the test too.
74	func runRouter(t *testing.T, a *App, profile colorprofile.Profile, script routerScript) (string, error) {
75		t.Helper()
76		return runRouterTo(t, a, profile, &lockedBuffer{}, script)
77	}
78	
79	// runRouterTo is runRouter with the output buffer chosen by the caller, for a
80	// fake that must read what the program has written.
81	func runRouterTo(t *testing.T, a *App, profile colorprofile.Profile, out *lockedBuffer, script routerScript) (string, error) {
82		t.Helper()
83		p := tea.NewProgram(a, tea.WithInput(nil), tea.WithOutput(out),
84			tea.WithWindowSize(100, 30), tea.WithoutSignalHandler(), tea.WithColorProfile(profile))
85		scriptErr := make(chan error, 1)
86		go func() {
87			err := waitOut(out, "the first frame", func(s string) bool { return strings.Contains(s, "hello") })
88			if err == nil && profile != colorprofile.Ascii {
89				// The first SET may land after the first frame; an exit sent
90				// before it would race with the write of the SET.
91				err = waitOut(out, "the first background SET", func(s string) bool { return strings.Contains(s, bgSet) })
92			}
93			if err == nil {
94				err = script(p, out)
95			}
96			if err != nil {
97				p.Kill()
98			}
99			scriptErr <- err
100		}()
101		type result struct{ err error }
102		done := make(chan result, 1)
103		go func() { _, err := p.Run(); done <- result{err} }()
104		var r result
105		select {
106		case r = <-done:
107		case <-time.After(10 * time.Second):
108			p.Kill()
109			if err := <-scriptErr; err != nil {
110				t.Errorf("script: %v", err)
111			}
112			t.Fatal("the program did not exit")
113		}
114		if err := <-scriptErr; err != nil {
115			t.Errorf("script: %v", err)
116		}
117		return out.String(), r.err
118	}
119	
120	func endsWithReset(t *testing.T, out string) {
121		t.Helper()
122		seqs := bgSequences(out)
123		if len(seqs) == 0 || seqs[len(seqs)-1] != bgReset {
124			t.Errorf("bgSequences = %q, want a last element %q", seqs, bgReset)
125		}
126	}
127	
128	func defaultHex() string {
129		theme.ApplyTheme(theme.DefaultTheme())
130		return theme.Hex(theme.ColorBackground)
131	}
132	
133	func programRouter(t *testing.T, v Screen) *App {
134		t.Helper()
135		resetThemeAfter(t)
136		return router(t, v)
137	}
138	
139	func TestBackgroundOnNormalQuit(t *testing.T) {
140		a := programRouter(t, &fakeView{body: "hello"})
141		out, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, _ *lockedBuffer) error { p.Quit(); return nil })
142		if err != nil {
143			t.Fatal(err)
144		}
145		seqs := bgSequences(out)
146		if len(seqs) < 2 || seqs[0] != setOf(defaultHex()) || seqs[len(seqs)-1] != bgReset {
147			t.Errorf("bgSequences = %q, want [%q ... %q]", seqs, setOf(defaultHex()), bgReset)
148		}
149	}
150	
151	func TestBackgroundOnCtrlC(t *testing.T) {
152		a := programRouter(t, &fakeView{body: "hello"})
153		out, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, _ *lockedBuffer) error {
154			p.Send(testutil.Key("ctrl+c"))
155			return nil
156		})
157		if err != nil {
158			t.Fatal(err)
159		}
160		endsWithReset(t, out)
161	}
162	
163	func TestBackgroundOnInterrupt(t *testing.T) {
164		a := programRouter(t, &fakeView{body: "hello"})
165		out, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, _ *lockedBuffer) error {
166			p.Send(tea.InterruptMsg{})
167			return nil
168		})
169		if !errors.Is(err, tea.ErrInterrupted) {
170			t.Errorf("err = %v, want tea.ErrInterrupted", err)
171		}
172		endsWithReset(t, out)
173	}
174	
175	func TestBackgroundOnKill(t *testing.T) {
176		a := programRouter(t, &fakeView{body: "hello"})
177		out, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, _ *lockedBuffer) error { p.Kill(); return nil })
178		if !errors.Is(err, tea.ErrProgramKilled) {
179			t.Errorf("err = %v, want tea.ErrProgramKilled", err)
180		}
181		endsWithReset(t, out)
182	}
183	
184	// panicView panics on a key.
185	type panicView struct{ fakeView }
186	
187	func (v *panicView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
188		if _, ok := msg.(tea.KeyPressMsg); ok {
189			panic("boom from a view")
190		}
191		return v, nil
192	}
193	
194	func TestBackgroundOnPanic(t *testing.T) {
195		a := programRouter(t, &panicView{fakeView{body: "hello"}})
196		out, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, _ *lockedBuffer) error {
197			p.Send(testutil.Key("x"))
198			return nil
199		})
200		if !errors.Is(err, tea.ErrProgramPanic) {
201			t.Errorf("err = %v, want tea.ErrProgramPanic", err)
202		}
203		endsWithReset(t, out)
204	}
205	
206	func TestBackgroundOnAThemeChangeInSession(t *testing.T) {
207		a := programRouter(t, &fakeView{body: "hello"})
208		writeTheme(t, "light", "#ffffff")
209		out, err := runRouter(t, a, colorprofile.TrueColor, func(p *tea.Program, out *lockedBuffer) error {
210			cfg := testConfig()
211			cfg.App.Theme = "light"
212			p.Send(themeSaved(cfg))
213			err := waitOut(out, "the light background", func(s string) bool { return strings.Contains(s, setOf("#ffffff")) })
214			p.Quit()
215			return err
216		})
217		if err != nil {
218			t.Fatal(err)
219		}
220		seqs := bgSequences(out)
221		want := []string{setOf("#1e1e2e"), setOf("#ffffff"), bgReset}
222		if strings.Join(seqs, "|") != strings.Join(want, "|") {
223			t.Errorf("bgSequences = %q, want %q", seqs, want)
224		}
225	}
226	
227	func TestBackgroundOnASCIIWritesNothing(t *testing.T) {
228		a := programRouter(t, &fakeView{body: "hello"})
229		out, err := runRouter(t, a, colorprofile.Ascii, func(p *tea.Program, _ *lockedBuffer) error {
230			// Messages are handled in order: the router has recorded the ASCII
231			// profile by the time it handles the quit.
232			p.Send(tea.ColorProfileMsg{Profile: colorprofile.Ascii})
233			p.Quit()
234			return nil
235		})
236		if err != nil {
237			t.Fatal(err)
238		}
239		if strings.Contains(out, "\x1b]11") {
240			t.Errorf("ASCII profile wrote a background sequence: %q", bgSequences(out))
241		}
242	}
243	
244	func REDACTED(t *testing.T) {
245		a := programRouter(t, &fakeView{body: "hello"})
246		out, err := runRouter(t, a, colorprofile.ANSI256, func(p *tea.Program, _ *lockedBuffer) error { p.Quit(); return nil })
247		if err != nil {
248			t.Fatal(err)
249		}
250		seqs := bgSequences(out)
251		// theme.Hex does not read an indexed colour; take its RGB like the terminal does.
252		r, g, b, _ := colorprofile.ANSI256.Convert(theme.ColorBackground).RGBA()
253		want := setOf(fmt.Sprintf("#%02x%02x%02x", r>>8, g>>8, b>>8))
254		if len(seqs) < 2 || seqs[0] != want {
255			t.Fatalf("bgSequences = %q, want first %q", seqs, want)
256		}
257		if seqs[0] == setOf("#1e1e2e") {
258			t.Error("ANSI256 set the exact colour instead of the converted one")
259		}
260		endsWithReset(t, out)
261	}
262	
263	// fakeExec stands in for the child of tea.Exec. During Run it snapshots what
264	// the program has written so far: the child must see the terminal's own
265	// background, so the last background sequence before Run is a reset.
266	type fakeExec struct {
267		out *lockedBuffer
268		err error
269	
270		mu       sync.Mutex
271		captured string
272	}
273	
274	func (f *fakeExec) Run() error {
275		f.mu.Lock()
276		f.captured = f.out.String()
277		f.mu.Unlock()
278		return f.err
279	}
280	func (f *fakeExec) SetStdin(io.Reader)  {}
281	func (f *fakeExec) SetStdout(io.Writer) {}
282	func (f *fakeExec) SetStderr(io.Writer) {}
283	
284	func (f *fakeExec) snapshot() string {
285		f.mu.Lock()
286		defer f.mu.Unlock()
287		return f.captured
288	}
289	
290	// execView runs fe through tea.Exec on a key and reports cb's error.
291	type execView struct {
292		fakeView
293		fe *fakeExec
294		cb chan error
295	}
296	
297	func (v *execView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
298		if _, ok := msg.(tea.KeyPressMsg); ok {
299			return v, tea.Exec(v.fe, func(err error) tea.Msg { v.cb <- err; return nil })
300		}
301		return v, nil
302	}
303	
304	func testExec(t *testing.T, runErr error) {
305		t.Helper()
306		out := &lockedBuffer{}
307		fe := &fakeExec{out: out, err: runErr}
308		v := &execView{fakeView: fakeView{body: "hello"}, fe: fe, cb: make(chan error, 1)}
309		a := programRouter(t, v)
310	
311		got, err := runRouterTo(t, a, colorprofile.TrueColor, out, func(p *tea.Program, _ *lockedBuffer) error {
312			p.Send(testutil.Key("x"))
313			select {
314			case cbErr := <-v.cb:
315				if !errors.Is(cbErr, runErr) {
316					return fmt.Errorf("exec callback got %v, want %v", cbErr, runErr)
317				}
318			case <-time.After(5 * time.Second):
319				return errors.New("the exec callback never ran")
320			}
321			// The terminal comes back: wait for a SET after the child's snapshot.
322			err := waitOut(out, "the background after the child", func(s string) bool {
323				return len(s) > len(fe.snapshot()) && strings.Contains(s[len(fe.snapshot()):], bgSet)
324			})
325			p.Quit()
326			return err
327		})
328		if err != nil {
329			t.Fatal(err)
330		}
331	
332		captured := fe.snapshot()
333		if captured == "" {
334			t.Fatal("the child never ran")
335		}
336		before := bgSequences(captured)
337		if len(before) < 2 || before[0] != setOf(defaultHex()) || before[len(before)-1] != bgReset {
338			t.Errorf("before the child: bgSequences = %q, want [SET ... RESET]", before)
339		}
340		after := bgSequences(got[len(captured):])
341		if len(after) < 2 || after[0] != setOf(defaultHex()) || after[len(after)-1] != bgReset {
342			t.Errorf("after the child: bgSequences = %q, want [SET ... RESET]", after)
343		}
344	}
345	
346	func TestBackgroundAroundExecProcess(t *testing.T) { testExec(t, nil) }
347	
348	func TestBackgroundAroundExecProcessThatFails(t *testing.T) {
349		testExec(t, errors.New("child failed"))
350	}
